head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _11 : dummy_merge (Cell 병합 관련 옵션) 계열 - mergeCell / colMerge / colMergeTextAlign / colMergeValue
//     description 은 분리 샘플 공통(_1 과 동일).
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "mergeCell(선택) 파라미터로 Cell 의 병합 상태를 Excel 파일에 적용할지 설정합니다.",
        "mergeCell(선택) 파라미터를 'true' 로 설정 시 Cell 의 병합 상태를 그대로 Excel 파일에 적용합니다.",
        "mergeCell(선택) 파라미터를 'false' 로 설정 시 Cell 의 병합을 해제하여 Excel 파일에 적용합니다. (해제된 Cell 의 데이터는 병합 상태의 데이터로 전체 설정됩니다.)",
        "mergeCell(선택) 파라미터를 'true' 로 설정 시 excludeHiddenRows 파라미터는 항상 false 로 적용됩니다.",
        "mergeCell(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
        "colMerge(선택) 파라미터로 colMerge 속성값이 true 인 Column 의 병합 상태를 Excel 파일에 적용할지 설정합니다.",
        "colMerge(선택) 파라미터를 'true' 로 설정 시 colMerge 속성으로 병합된 Column 의 병합 상태를 그대로 Excel 파일에 적용합니다.",
        "colMerge(선택) 파라미터를 'false' 로 설정 시 colMerge 속성으로 병합된 Column 을 해제하여 Excel 파일에 적용합니다.",
        "colMerge(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
        "colMergeTextAlign(선택) 파라미터로 colMerge 파라미터값이 'true' 일때 colMerge 속성으로 병합된 Cell 의 수직 정렬을 'top'/'center'/'bottom' 으로 설정합니다.",
        "colMergeTextAlign(선택) 파라미터를 'top' 으로 설정 시 colMerge 속성으로 병합된 Cell 의 수직 정렬이 'top' 으로 적용됩니다.",
        "colMergeTextAlign(선택) 파라미터를 'center' 로 설정 시 colMerge 속성으로 병합된 Cell 의 수직 정렬이 'center' 로 적용됩니다.",
        "colMergeTextAlign(선택) 파라미터를 'bottom' 으로 설정 시 colMerge 속성으로 병합된 Cell 의 수직 정렬이 'bottom' 으로 적용됩니다.",
        "colMergeTextAlign(선택) 파라미터를 생략하면 기본값 'center' 가 적용됩니다.",
        "colMergeValue(선택) 파라미터로 병합된 Cell 을 Excel 파일에서 사용자가 해제할때 각 Cell 에 데이터를 채울지 설정합니다.",
        "colMergeValue(선택) 파라미터를 'true' 로 설정 시 병합이 해제된 모든 Cell 에 동일 데이터가 설정됩니다.",
        "colMergeValue(선택) 파라미터를 'false' 로 설정 시 병합이 해제된 Cell 의 첫 행이나 첫 열에만 데이터가 설정됩니다.",
        "colMergeValue(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : 두 가지 방식으로 Cell 이 병합된 GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · Body Column 인덱스 0:구분 1:품목 2:보관위치 3:담당자 / Body Row 는 6행
//    - 구분     : mergeCell() 메소드로 Row 0~2 / Row 3~5 를 병합 (mergeCell 파라미터 확인용)
//    - 보관위치 : colMerge 속성이 true 인 Column 으로 값이 같은 연속 Row 가 자동 병합
//                 (colMerge / colMergeTextAlign 파라미터 확인용)
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Body Column 인덱스 0 구분 / 1 품목 / 2 보관위치 / 3 담당자, Body Row 는 6행\n- 구분 Column 은 mergeCell() 메소드로 Row 0~2 (사무기기) / Row 3~5 (전산소모품) 를 Cell 병합함\n- 보관위치 Column 은 colMerge 속성이 true 라서 값이 같은 연속 Row 가 자동 병합됨 (Row 0~1 본관 3층 / Row 2~4 별관 1층 / Row 5 창고동)\n- excludeHiddenRows 는 본 계열의 검증 대상이 아니며, mergeCell 하위 조건(mergeCell 이 true 이면 excludeHiddenRows 는 항상 false 로 적용) 확인용 보조 옵션임\n- 파일명 download_mergecell, 확장자 xlsx 고정 전달(본 계열 검증 대상 아님)\n[절차]\n1. excludeHiddenRows 를 확인하려면 먼저 Row 숨기기 (setRowVisible) 버튼으로 Row 1, 4 를 숨긴다 (되돌리려면 Row 숨김 해제 버튼)\n2. par 옵션(mergeCell / colMerge / colMergeTextAlign / colMergeValue / excludeHiddenRows) 값을 선택한다\n3. advancedExcelDownload 버튼을 클릭해 Excel 파일을 내려받는다\n[확인]\n- 결과창의 서버 전달값은 실제로 서버에 전송된 옵션 원문이며, 병합 정보(mergeCellInfo) 는 mergeCell() 메소드로 병합한 영역의 좌표(x=Column, y=Row, r=rowSpan, c=colSpan)임\n- mergeCell : true 면 내려받은 Excel 파일의 구분 Column 이 Row 0~2 / Row 3~5 범위로 병합되어 있고, false 또는 미설정이면 병합이 없이 각 Cell 에 사무기기 / 전산소모품 값이 모두 들어 있는지\n- colMerge : true 면 보관위치 Column 이 값이 같은 연속 Row 끼리 병합되어 있고, false 또는 미설정이면 병합이 해제되어 있는지\n- colMergeTextAlign : colMerge 가 true 일 때 병합된 보관위치 Cell 의 값이 위쪽(top) / 가운데(center) / 아래쪽(bottom) 중 어디에 세로 정렬되는지 (Excel 에서 해당 Cell 의 맞춤(세로) 서식으로 확인)\n- colMergeValue : Excel 에서 병합을 해제했을 때 true 면 병합 범위의 모든 Cell 에 같은 값이 채워지는지, false 또는 미설정이면 병합 범위의 첫 Cell 에만 값이 있는지 (mergeCell 로 병합한 구분 Column 과 colMerge 속성으로 병합된 보관위치 Column 을 각각 확인)\n- 주의 : colMergeValue 는 colMerge 속성으로 병합된 Column 에만 적용되며 mergeCell 로 병합한 Column 에는 미지원이다. mergeCell 병합 Column 에서 colMergeValue 를 false 로 설정하면 첫 Cell 과 마지막 Cell 두 곳에 값이 남지만 이는 미지원 조합의 동작이다\n- excludeHiddenRows : Row 1, 4 를 숨긴 뒤 excludeHiddenRows 와 mergeCell 을 함께 true 로 설정했을 때 결과창의 서버 전달 데이터 Row 수를 확인"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="category" name="category" dataType="text"></w2:column>';
    strDlt += '<w2:column id="item" name="item" dataType="text"></w2:column>';
    strDlt += '<w2:column id="location" name="location" dataType="text"></w2:column>';
    strDlt += '<w2:column id="manager" name="manager" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "category" : "사무기기",   "item" : "모니터 27인치",  "location" : "본관 3층", "manager" : "홍길동" },
        { "category" : "사무기기",   "item" : "노트북 15인치",  "location" : "본관 3층", "manager" : "김담당" },
        { "category" : "사무기기",   "item" : "모니터암 듀얼",  "location" : "별관 1층", "manager" : "이관리" },
        { "category" : "전산소모품", "item" : "무선 마우스",    "location" : "별관 1층", "manager" : "박비품" },
        { "category" : "전산소모품", "item" : "기계식 키보드",  "location" : "별관 1층", "manager" : "최자산" },
        { "category" : "전산소모품", "item" : "노이즈캔슬 헤드셋", "location" : "창고동", "manager" : "정운영" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 생성 (DataList 바인딩)
    //  · 보관위치 Column 에 colMerge="true" 를 설정하여 값이 같은 연속 Row 를 자동 병합한다.
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:820px;height:280px;">';
    strTarget += '<w2:caption style="" id="caption1" value="advancedExcelDownload (Cell 병합 옵션) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="구분"></w2:column>';
    strTarget += '<w2:column width="240" style="" inputType="text" id="hcol2" value="품목"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol3" value="보관위치"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="담당자"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="category" dataList="category"></w2:column>';
    strTarget += '<w2:column width="240" style="" inputType="text" id="item" dataList="item"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="location" dataList="location" colMerge="true"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="manager" dataList="manager"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 구분 Column Cell 병합 (mergeCell 파라미터 확인용)
    target1.mergeCell({ "rowIndex" : 0, "colIndex" : 0, "colSpan" : 1, "rowSpan" : 3 });
    target1.mergeCell({ "rowIndex" : 3, "colIndex" : 0, "colSpan" : 1, "rowSpan" : 3 });
}



// setRowVisible() 로 Row 1, 4 를 숨긴다. (mergeCell 하위 조건 확인 전제 - JS 로만 설정 가능한 상태)
scwin.btn_hideRow_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.setRowVisible(1, false);
    target1.setRowVisible(4, false);

    bottom.setReturnValue("숨긴 Row : 1, 4 (표시 Row 수 4 / 전체 Row 수 6)");
}



// 숨긴 Row 를 다시 표시한다.
scwin.btn_showRow_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.setRowVisible(1, true);
    target1.setRowVisible(4, true);

    bottom.setReturnValue("숨김 해제 Row : 1, 4 (표시 Row 수 6 / 전체 Row 수 6)");
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · excludeHiddenRows 는 Boolean 타입 파라미터이므로 Boolean 으로 변환하여 전달하며,
//    본 계열의 검증 대상이 아니고 mergeCell 의 하위 조건 확인용 보조 옵션이다.
//  · fileName / extension 은 다운로드 파일 확인 편의를 위한 고정값이며 본 계열의 검증 대상이 아니다.
scwin.buildOptions = function () {
    let options = { "fileName" : "download_mergecell", "extension" : "xlsx" };
    let arrDesc = [];

    let fnSet = function (sKey, vValue) {
        options[sKey] = vValue;
        arrDesc.push(sKey + "=" + vValue);
    };

    let v;
    v = par_mergeCell.getValue();         if (v !== "") fnSet("mergeCell", v);
    v = par_colMerge.getValue();          if (v !== "") fnSet("colMerge", v);
    v = par_colMergeTextAlign.getValue(); if (v !== "") fnSet("colMergeTextAlign", v);
    v = par_colMergeValue.getValue();     if (v !== "") fnSet("colMergeValue", v);
    v = par_excludeHiddenRows.getValue(); if (v !== "") fnSet("excludeHiddenRows", (v === "true"));

    return { "options" : options, "desc" : ((arrDesc.length === 0) ? "{} (mergeCell / colMerge / colMergeTextAlign / colMergeValue / excludeHiddenRows 전체 생략)" : arrDesc.join(" / ")) };
}



// 다운로드 요청 캡처 : 다운로드는 숨겨진 iframe 으로 form 전송되며 form 은 전송 직후 제거되므로,
//  메소드 호출 구간에서만 form submit 을 감싸 서버로 실제 전달되는 값을 읽고 곧바로 원복한다. (실제 요청은 그대로 통과)
scwin.hookRequest = function () {
    scwin.gVar = { "body" : "" };

    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        if (scwin.gVar.body === "") {
            let objInput = this.querySelector("input[name=xmlValue]");
            scwin.gVar.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
    };
}



// 캡처한 요청 본문에서 서버로 전달된 옵션값을 읽는다. (전달되지 않은 옵션은 미전달로 표시)
scwin.getSentValue = function (sKey) {
    let sBody = scwin.gVar.body || "";
    let nKey = sBody.indexOf("hashkey='" + sKey + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nVal = sRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    sRest = sRest.substring(nVal + 7);
    return sRest.substring(0, sRest.indexOf("'"));
}



// 캡처한 요청 본문에서 배열 형태로 전달된 값(CDATA 원문)을 읽는다.
scwin.getSentArray = function (sKey) {
    let sBody = scwin.gVar.body || "";
    let nKey = sBody.indexOf("hashkey='" + sKey + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nStart = sRest.indexOf("<![CDATA[");
    let nEnd = sRest.indexOf("]" + "]>");
    if (nStart < 0 || nEnd < 0) return "(미확인)";

    return sRest.substring(nStart + 9, nEnd);
}



// 서버로 전달된 데이터의 Row 수를 센다. (Body Cell 값 배열의 길이를 Column 수 4 로 나눈 값)
scwin.getSentRowCount = function () {
    let sData = scwin.getSentArray("data");
    let arrData = null;
    try {
        arrData = JSON.parse(sData);
    } catch (e) {
        return "(미확인)";
    }
    if (arrData === null || typeof arrData.length !== "number") return "(미확인)";
    return (arrData.length / 4);
}



// advancedExcelDownload 실행
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objBuild = scwin.buildOptions();

    scwin.hookRequest();
    try {
        target1.advancedExcelDownload(objBuild.options);
    } finally {
        scwin.gVar.unhook();
    }

    bottom.setReturnValue("전달 옵션 : " + objBuild.desc);
    bottom.setReturnValue("서버 전달값 : mergeCell=" + scwin.getSentValue("mergeCell") + " / colMerge=" + scwin.getSentValue("colMerge") + " / colMergeTextAlign=" + scwin.getSentValue("colMergeTextAlign") + " / colMergeValue=" + scwin.getSentValue("colMergeValue"));
    bottom.setReturnValue("서버 전달 병합 정보(mergeCellInfo) : " + scwin.getSentArray("mergeCellInfo"));
    bottom.setReturnValue("서버 전달 데이터 Row 수 : " + scwin.getSentRowCount() + " (전체 Row 수 6)");
}
